package com.campusnova.service;
import org.springframework.stereotype.Service; import java.util.*;
/** Small local semantic signal: meaningful token overlap plus related campus-language families. */
@Service public class SemanticTextService { private static final Map<String,String> RELATED=new HashMap<String,String>(); private static final Set<String> STOP=new HashSet<String>(Arrays.asList("what","when","where","who","why","how","are","the","and","for","with","from","this","that","can","does","your","our","about","tell","please","would","could","should","have","has","was","were","use","get","any","all")); static {family("library","library books reading borrow open close hours timing");family("timing","time hours open close schedule timetable");family("fee","fee payment tuition scholarship account");family("admission","admission apply application document enrollment");family("exam","exam examination test result missed");family("placement","placement internship career recruitment job");family("transport","bus transportation route leave campus");family("facility","lab laboratory hostel club campus department");} private static void family(String root,String words){for(String raw:words.split(" "))RELATED.put(normalize(raw),root);} private static String normalize(String raw){return raw.length()>4&&raw.endsWith("s")?raw.substring(0,raw.length()-1):raw;} public double score(String question,Collection<String> memory,String content){Set<String> q=terms(question);for(String m:memory)q.addAll(terms(m));Set<String> c=terms(content);if(q.isEmpty()||c.isEmpty())return 0;int hits=0;for(String word:q)if(c.contains(word)||hasRelated(word,c))hits++;return (double)hits/q.size();} public Set<String> terms(String value){Set<String> result=new HashSet<String>();if(value==null)return result;for(String raw:value.toLowerCase().replaceAll("[^a-z0-9 ]"," ").split("\\s+")){String w=normalize(raw);if(w.length()>2&&!STOP.contains(w))result.add(w);}return result;} private boolean hasRelated(String word,Set<String> content){String family=RELATED.get(word);if(family==null)return false;for(String other:content)if(family.equals(RELATED.get(other)))return true;return false;} }
